KaluzaKlein.Sets.Composition.Rz_mul_Rx.statement:
theorem Rz_mul_Rx (α β : ℝ) : Rz α * Rx β =
    !![Real.cos α, -(Real.sin α * Real.cos β), Real.sin α * Real.sin β;
       Real.sin α, Real.cos α * Real.cos β, -(Real.cos α * Real.sin β);
       0, Real.sin β, Real.cos β]

KaluzaKlein.Sets.Products.torus_pairs_of.statement:
theorem torus_pairs_of_angles (r₁ r₂ : ℝ) (h₁ : 0 ≤ r₁) (h₂ : 0 ≤ r₂) :
    Set.range (fun q : ℝ × ℝ => ((r₁ * Real.cos q.1, r₁ * Real.sin q.1), (r₂ * Real.cos q.2, r₂ * Real.sin q.2))) =
      {p : ℝ × ℝ | p.1 ^ 2 + p.2 ^ 2 = r₁ ^ 2} ×ˢ {p : ℝ × ℝ | p.1 ^ 2 + p.2 ^ 2 = r₂ ^ 2}

KaluzaKlein.Sets.Composition.Rx_mul_Rz.statement:
theorem Rx_mul_Rz (α β : ℝ) : Rx β * Rz α =
    !![Real.cos α, -Real.sin α, 0;
       Real.cos β * Real.sin α, Real.cos β * Real.cos α, -Real.sin β;
       Real.sin β * Real.sin α, Real.sin β * Real.cos α, Real.cos β]

KaluzaKlein.Sets.Bijective.int_affine.statement:
theorem int_affine (b : ℤ) (hb : Odd b) :
    Function.Injective (fun k : ℤ => 2 * k + b) ∧ ¬ Function.Surjective (fun k : ℤ => 2 * k + b) ∧
      Set.range (fun k : ℤ => 2 * k + b) = {n | Odd n}

KaluzaKlein.RealAnalysis.Calculus.spheri.statement:
theorem spherical_inverse_row (r θ φ : ℝ) :
    !![Real.sin θ * Real.cos φ, Real.sin θ * Real.sin φ, Real.cos θ] *
      !![Real.sin θ * Real.cos φ, r * Real.cos θ * Real.cos φ, -r * Real.sin θ * Real.sin φ;
        Real.sin θ * Real.sin φ, r * Real.cos θ * Real.sin φ, r * Real.sin θ * Real.cos φ;
        Real.cos θ, -r * Real.sin θ, 0] = !![1, 0, 0]

theorem spherical_jacobian_det (r θ φ : ℝ) :
    Matrix.det !![Real.sin θ * Real.cos φ, r * Real.cos θ * Real.cos φ, -r * Real.sin θ * Real.sin φ;
      Real.sin θ * Real.sin φ, r * Real.cos θ * Real.sin φ, r * Real.sin θ * Real.cos φ;
      Real.cos θ, -r * Real.sin θ, 0] = r ^ 2 * Real.sin θ

KaluzaKlein.RealAnalysis.Sequences.sq_lt.statement:
theorem sq_lt_bounds (p : ℝ) (hp : 0 < p) :
    IsLUB {x : ℝ | x ^ 2 < p} (√p) ∧ IsGLB {x : ℝ | x ^ 2 < p} (-√p) ∧
      √p ∉ {x : ℝ | x ^ 2 < p} ∧ -√p ∉ {x : ℝ | x ^ 2 < p}

KaluzaKlein.ComplexAnalysis.Branches.sqr.statement:
theorem sqrt_branch_outer_cuts (c : ℂ) :
    IsBranch (fun z => {w | w ^ 2 = z ^ 2 - c}) {z | c - z ^ 2 ∈ slitPlane}
      (fun z => I * (c - z ^ 2) ^ (1 / 2 : ℂ))

KaluzaKlein.DifferentialEquations.Linear.statement:
theorem spiral_initial :
    !![Real.exp (-0) * (Real.cos 0 + Real.sin 0), Real.exp (-0) * Real.sin 0;
      Real.exp (-0) * (-2 * Real.sin 0), Real.exp (-0) * (Real.cos 0 - Real.sin 0)] = (1 : Matrix (Fin 2) (Fin 2) ℝ)

theorem cube_derivative (t : ℝ) :
    !![(0 : ℝ), 1, 0; 0, 0, 1; 0, -1, 0] *
        !![1, Real.sin t, 1 - Real.cos t; 0, Real.cos t, Real.sin t; 0, -Real.sin t, Real.cos t] =
      !![0, deriv (fun s => Real.sin s) t, deriv (fun s => 1 - Real.cos s) t;
        0, deriv (fun s => Real.cos s) t, deriv (fun s => Real.sin s) t;
        0, deriv (fun s => -Real.sin s) t, deriv (fun s => Real.cos s) t]

KaluzaKlein.FourierAnalysis.MatrixCoeffi.statement:
theorem d1_orthogonal (θ : ℝ) :
    !![(1 + Real.cos θ) / 2, -(Real.sqrt 2 / 2) * Real.sin θ, (1 - Real.cos θ) / 2;
       Real.sqrt 2 / 2 * Real.sin θ, Real.cos θ, -(Real.sqrt 2 / 2) * Real.sin θ;
       (1 - Real.cos θ) / 2, Real.sqrt 2 / 2 * Real.sin θ, (1 + Real.cos θ) / 2] *
    (!![(1 + Real.cos θ) / 2, -(Real.sqrt 2 / 2) * Real.sin θ, (1 - Real.cos θ) / 2;
       Real.sqrt 2 / 2 * Real.sin θ, Real.cos θ, -(Real.sqrt 2 / 2) * Real.sin θ;
       (1 - Real.cos θ) / 2, Real.sqrt 2 / 2 * Real.sin θ, (1 + Real.cos θ) / 2])ᵀ = 1

theorem character_trace (θ : ℝ) :
    Matrix.trace !![(1 + Real.cos θ) / 2, -(Real.sqrt 2 / 2) * Real.sin θ, (1 - Real.cos θ) / 2;
       Real.sqrt 2 / 2 * Real.sin θ, Real.cos θ, -(Real.sqrt 2 / 2) * Real.sin θ;
       (1 - Real.cos θ) / 2, Real.sqrt 2 / 2 * Real.sin θ, (1 + Real.cos θ) / 2] = 1 + 2 * Real.cos θ

theorem d1_zero :
    !![(1 + Real.cos 0) / 2, -(Real.sqrt 2 / 2) * Real.sin 0, (1 - Real.cos 0) / 2;
       Real.sqrt 2 / 2 * Real.sin 0, Real.cos 0, -(Real.sqrt 2 / 2) * Real.sin 0;
       (1 - Real.cos 0) / 2, Real.sqrt 2 / 2 * Real.sin 0, (1 + Real.cos 0) / 2] = (1 : Matrix (Fin 3) (Fin 3) ℝ)

theorem double_cover_one :
    !![(1 + Real.cos (2 * π)) / 2, -(Real.sqrt 2 / 2) * Real.sin (2 * π), (1 - Real.cos (2 * π)) / 2;
       Real.sqrt 2 / 2 * Real.sin (2 * π), Real.cos (2 * π), -(Real.sqrt 2 / 2) * Real.sin (2 * π);
       (1 - Real.cos (2 * π)) / 2, Real.sqrt 2 / 2 * Real.sin (2 * π), (1 + Real.cos (2 * π)) / 2] =
      (1 : Matrix (Fin 3) (Fin 3) ℝ)

theorem d1_deriv (θ : ℝ) (i j : Fin 3) :
    HasDerivAt (fun θ => d1 θ i j)
      (!![-Real.sin θ / 2, -(Real.sqrt 2 / 2) * Real.cos θ, Real.sin θ / 2;
         Real.sqrt 2 / 2 * Real.cos θ, -Real.sin θ, -(Real.sqrt 2 / 2) * Real.cos θ;
         Real.sin θ / 2, Real.sqrt 2 / 2 * Real.cos θ, -Real.sin θ / 2] i j) θ

theorem d1_det (θ : ℝ) :
    Matrix.det !![(1 + Real.cos θ) / 2, -(Real.sqrt 2 / 2) * Real.sin θ, (1 - Real.cos θ) / 2;
       Real.sqrt 2 / 2 * Real.sin θ, Real.cos θ, -(Real.sqrt 2 / 2) * Real.sin θ;
       (1 - Real.cos θ) / 2, Real.sqrt 2 / 2 * Real.sin θ, (1 + Real.cos θ) / 2] = 1

theorem d1_ode (θ : ℝ) :
    !![-Real.sin θ / 2, -(Real.sqrt 2 / 2) * Real.cos θ, Real.sin θ / 2;
       Real.sqrt 2 / 2 * Real.cos θ, -Real.sin θ, -(Real.sqrt 2 / 2) * Real.cos θ;
       Real.sin θ / 2, Real.sqrt 2 / 2 * Real.cos θ, -Real.sin θ / 2] =
    !![0, -(Real.sqrt 2 / 2), 0; Real.sqrt 2 / 2, 0, -(Real.sqrt 2 / 2); 0, Real.sqrt 2 / 2, 0] *
    !![(1 + Real.cos θ) / 2, -(Real.sqrt 2 / 2) * Real.sin θ, (1 - Real.cos θ) / 2;
       Real.sqrt 2 / 2 * Real.sin θ, Real.cos θ, -(Real.sqrt 2 / 2) * Real.sin θ;
       (1 - Real.cos θ) / 2, Real.sqrt 2 / 2 * Real.sin θ, (1 + Real.cos θ) / 2]

KaluzaKlein.Geometry.su2_invMetric.statement:
theorem su2_invMetric (x : Fin 3 → ℝ) (h : Real.sin (x 0) ≠ 0) :
    invMetric su2 x =
      !![(4 : ℝ), 0, 0;
         0, 4 / Real.sin (x 0) ^ 2, -4 * Real.cos (x 0) / Real.sin (x 0) ^ 2;
         0, -4 * Real.cos (x 0) / Real.sin (x 0) ^ 2, 4 / Real.sin (x 0) ^ 2]
